// por isso vão em base64 dentro do CSS (como recomenda a documentação do 10tap).
/* eslint-disable */
export const EDITOR_FONTS_CSS = "@font-face { font-family: 'Sen'; font-weight: 400; src: url(data:font/ttf;base64,) format('truetype'); }\n@font-face { font-family: 'Sen'; font-weight: 600 700; src: url(data:font/ttf;base64,) format('truetype'); }\n@font-face { font-family: 'Red Hat Display'; font-weight: 700; src: url(data:font/ttf;base64,) format('truetype'); }";
